const TITLES = ['AI Deployment Strategist', 'AI Strategy Lead', 'AI Deployment Lead'];
const LOCATIONS = ['New York', 'San Francisco', 'London'];
const queries = [];
for (const title of TITLES) {
  for (const loc of LOCATIONS) {
    queries.push({ json: { query: `${title} in ${loc}`, title, location: loc } });
  }
}
return queries;

