const TITLE_KEYWORDS = [
  'ai deployment strategist',
  'ai deployment lead',
  'ai strategy',
  'ai strategist',
  'deployment strategist',
];
function matches(t) { t = (t || '').toLowerCase(); return TITLE_KEYWORDS.some(k => t.includes(k)); }
function makeKey(source, url, title, company) {
  return `${source}::${url || `${company || ''}::${title}`}`.toLowerCase().slice(0, 500);
}
const jobs = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (Array.isArray(j.data) && j.data[0]?.job_title !== undefined) {
    for (const r of j.data) {
      if (!matches(r.job_title)) continue;
      jobs.push({
        job_key: makeKey('jsearch', r.job_apply_link, r.job_title, r.employer_name),
        title: r.job_title,
        company: r.employer_name || null,
        location: [r.job_city, r.job_state, r.job_country].filter(Boolean).join(', ') || null,
        source: 'jsearch',
        url: r.job_apply_link || null,
        posted_at: r.job_posted_at_datetime_utc || null,
      });
    }
  }
  if (Array.isArray(j.data) && j.data[0]?.url !== undefined) {
    for (const r of j.data) {
      if (!matches(r.title)) continue;
      jobs.push({
        job_key: makeKey('firecrawl', r.url, r.title, null),
        title: r.title,
        company: null,
        location: null,
        source: 'firecrawl',
        url: r.url,
        posted_at: null,
      });
    }
  }
}
const seen = new Set();
const unique = jobs.filter(j => { if (seen.has(j.job_key)) return false; seen.add(j.job_key); return true; });
return unique.map(json => ({ json }));

const seen = new Set(($('Check Seen Jobs').all() || []).map(i => i.json.job_key));
const fresh = $('Normalize & Filter').all().filter(i => !seen.has(i.json.job_key));
return fresh;

const jobs = $('Keep Only New').all().map(i => i.json);
if (jobs.length === 0) return [{ json: { skip: true, count: 0 } }];
const rows = jobs.map(j => `<tr><td style="padding:8px;border-bottom:1px solid #eee"><a href="${j.url || '#'}" style="color:#1a73e8;text-decoration:none;font-weight:600">${j.title}</a><br><span style="color:#666;font-size:13px">${j.company || ''} ${j.location ? '— ' + j.location : ''}</span><br><span style="color:#999;font-size:12px">${j.source}</span></td></tr>`).join('');
const html = `<!doctype html><html><body style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;max-width:640px;margin:0 auto;padding:24px"><h2 style="color:#111">${jobs.length} new AI Deployment role${jobs.length===1?'':'s'} today</h2><table style="width:100%;border-collapse:collapse">${rows}</table><p style="color:#999;font-size:12px;margin-top:24px">Sent by your n8n job-hunting agent</p></body></html>`;
return [{ json: { skip: false, count: jobs.length, html, subject: `${jobs.length} new AI Deployment role${jobs.length===1?'':'s'}` } }];
